fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len());

    for &c in str1.iter() {
        if ('a'..='z').contains(&c) {
            // Convert lowercase ASCII letter to uppercase by subtracting 32 from its u8 value
            // char as u8 is safe here because ASCII lowercase letters are in 0x61..0x7A range
            let uppercase_char = ((c as u8) - 32) as char;
            result.push(uppercase_char);
        } else {
            // Keep all other chars as is
            result.push(c);
        }
    }

    result
}